begin;
do $$
declare u uuid:='00000000-0000-0000-0000-0000000000b1'; outro uuid:='00000000-0000-0000-0000-0000000000b2'; chave uuid:=gen_random_uuid(); a jsonb; b jsonb; saldo bigint; categoria uuid; conta uuid; linha uuid; nova uuid;
begin
 insert into auth.users(id) values(u),(outro);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);
 insert into public.categorias(user_id,nome,tipo) values(u,'Recebimentos','RECEITA') returning id into categoria;
 a:=public.registrar_receita(chave,'Receita externa',10000,'TRANSFERENCIA','2026-10-20','Nota <script>teste</script>',categoria);
 b:=public.registrar_receita(chave,'Receita externa',10000,'TRANSFERENCIA','2026-10-20','Nota <script>teste</script>',categoria);
 if a->>'transacao_id'<>b->>'transacao_id' or not (b->>'repetida')::boolean then raise exception 'repetição duplicou';end if;
 if (select observacao from public.transacoes_origem where id=(a->>'transacao_id')::uuid)<>'Nota <script>teste</script>' then raise exception 'observação perdida';end if;
 if (select categoria_id from public.transacoes_origem where id=(a->>'transacao_id')::uuid)<>categoria then raise exception 'categoria perdida';end if;
 perform public.registrar_receita(gen_random_uuid(),'Pix recebido',5000,'PIX','2026-10-20',null,null);
 perform public.registrar_receita(gen_random_uuid(),'Dinheiro recebido',1000,'DINHEIRO','2026-10-20',null,null);
 perform public.processar_transacao_completa('Despesa à vista',3000,'DESPESA','PIX',null,'2026-10-20',1);
 select saldo_caixa into saldo from public.vw_carteira;
 if saldo<>13000 then raise exception 'sinal ou total incorreto: %',saldo;end if;
 b:=public.substituir_transacao((a->>'transacao_id')::uuid,'Receita editada',10000,'RECEITA','TRANSFERENCIA',null,'2026-10-20',1,categoria);
 nova:=(b->>'transacao_id')::uuid;
 if (select observacao from public.transacoes_origem where id=nova) is distinct from 'Nota <script>teste</script>' then raise exception 'edição perdeu observação';end if;
 b:=public.registrar_receita(chave,'Receita externa',10000,'TRANSFERENCIA','2026-10-20','Nota <script>teste</script>',categoria);
 if (b->>'transacao_id')::uuid<>nova or not (b->>'repetida')::boolean then raise exception 'edição perdeu idempotência';end if;
 conta:=(public.criar_conta_bancaria('Conta sintética',0,'2026-10-01')->>'id')::uuid;
 perform public.importar_extrato_conta(conta,'CSV','[{"data":"2026-10-20","valor":10000,"descricao":"Receita editada"}]');
 select id into linha from public.linhas_extrato_conta where conta_id=conta;
 perform public.conciliar_linha_conta(linha,'VINCULAR',nova,null,null);
 perform public.conciliar_linha_conta(linha,'VINCULAR',nova,null,null);
 if (select count(*) from public.movimentos_conta where conta_id=conta and transacao_id=nova and valor=10000)<>1 then raise exception 'transferência não conciliou exatamente uma vez';end if;
 select saldo_caixa into saldo from public.vw_carteira;
 if saldo<>13000 then raise exception 'conciliação duplicou caixa';end if;
 begin perform public.registrar_receita(chave,'Outro valor',100,'PIX','2026-10-20',null,null);raise exception 'chave conflitante aceita';exception when sqlstate 'FW409' then null;end;
 begin perform public.registrar_receita(gen_random_uuid(),'Receita no cartão',100,'CREDITO','2026-10-20',null,null);raise exception 'crédito aceito';exception when sqlstate 'FW400' then null;end;
 begin perform public.registrar_receita(gen_random_uuid(),'Nota longa',100,'PIX','2026-10-20',repeat('a',2001),null);raise exception 'nota longa aceita';exception when sqlstate 'FW400' then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outro)::text,true);
 begin perform public.registrar_receita(gen_random_uuid(),'Categoria alheia',100,'PIX','2026-10-20',null,categoria);raise exception 'categoria cruzada';exception when sqlstate 'FW404' then null;end;
 if exists(select 1 from public.transacoes_origem where user_id=outro) then raise exception 'falha deixou transação parcial';end if;
 if has_function_privilege('anon','public.registrar_receita(uuid,text,bigint,text,date,text,uuid)','execute') then raise exception 'anon autorizado';end if;
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-0000000000b2"}',true);
do $$ begin if exists(select 1 from public.transacoes_origem where observacao is not null) then raise exception 'leitura cruzada';end if;raise notice 'OK: todos os asserts de receitas, edição, repetição, conciliação e isolamento';end $$;
rollback;
